    {
      "object_type": "Image",
      "description": "Image is a 3D image plane that displays a texture in 3D world space. Unlike Screen Image which exists in 2D screen space, Image can be positioned, rotated, and scaled like any 3D object. Uses the Image component to directly assign a texture. WARNING: Image renders in the transparent queue with BOTH depth test and depth write disabled — overlap between two Images is resolved by draw order, not by the depth buffer, and an Image can be fully hidden behind another drawn later even when it is closer to the camera (typically when both transforms share the same world Z). For 2D-texture entities that must occlude each other correctly in a 3D scene (grounds, walls, standee characters), prefer Plane with a depth-tested material; reserve Image for isolated billboards that never overlap other world-space content.",
      "defaultComponents": {
        "main": [
          "Image"
        ]
      }
    },
    {
      "object_type": "Profile Photo",
      "description": "Legacy SocialKit Profile Photo object. It displays a TikTok friend's real profile image and auto-creates a 'Username' sibling Image under the same 2D Camera parent. Use it only for compatibility with existing SocialKit templates or when explicitly requested. For new friend-avatar/profile work, prefer APJS.SocialService: create normal Screen Image slots and assign returned UserProfile.profileTexture values in script. Profile Photo preview placeholders can vary by project, and SocialKit is being deprecated.",
      "defaultComponents": {
        "main": [
          "Image"
        ],
        "parent": {
          "name": "2D Camera",
          "components": [
            "Camera"
          ]
        },
        "siblings": [
          {
            "name": "Username",
            "components": [
              "Image"
            ]
          }
        ]
      }
    },
    {
      "object_type": "Screen Image",
      "description": "Screen Image creates a 2D image displayed in screen space (flat, non-perspective). When added, it automatically creates a companion 2D Camera (Orthographic) required to render 2D content. Supports importing PNG or JPG textures for backgrounds, UI elements, and overlays. SOLID-COLOR RECTANGLE: an Image with no texture renders as a gray placeholder, so do NOT generate/import an image just to get a colored panel — instead point the Image component's `texture` at the built-in white texture (a resource that already exists, no creation needed: set texture to { guid: \"r2\" }, the built-in White_Texture.png) and set `color` to tint it. The white texture multiplies with `color`, yielding a crisp solid-color fill; adjust `opacity` for transparency.",
      "defaultComponents": {
        "main": [
          "Image"
        ],
        "parent": {
          "name": "2D Camera",
          "components": [
            "Camera"
          ]
        }
      }
    },
    {
      "object_type": "2D Mask",
      "description": "2D Mask constrains the visible area of its child objects — any Screen Image, 2D Text, or texture placed as a child is clipped to the mask's defined region. Use it to create focused visuals, reveal effects, or control content visibility within a defined screen area.",
      "defaultComponents": {
        "main": [
          "Mask"
        ]
      }
    },
    {
      "object_type": "2D Scene Object",
      "description": "2D Scene Object is an invisible empty container for grouping other 2D objects under a shared Screen Transform. Child 2D objects can be manipulated together as a single unit. The 2D equivalent of the Empty Object. Automatically nested under a 2D Camera.",
      "defaultComponents": {
        "main": [],
        "parent": {
          "name": "2D Camera",
          "components": [
            "Camera"
          ]
        }
      }
    }
  ]
